# [local patch] 34-autostart-helpers：读写当前用户的开机启动项
def _autostart_exe() -> Path | None:
    bases: list[Path] = []
    for anchor in (root, Path(__file__).resolve()):
        bases.append(anchor)
        bases.extend(list(anchor.parents)[:10])
    for base in bases:
        for rel in ('LenBotDesktop/LenBot.exe', 'LenBot.exe'):
            candidate = base / rel
            if candidate.is_file():
                return candidate
    return None

def _autostart_read() -> dict:
    import sys as _sys
    exe = _autostart_exe()
    state = {'supported': _sys.platform == 'win32', 'enabled': False,
             'target': str(exe) if exe else None}
    if not state['supported']:
        return state
    import winreg
    try:
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, _AUTOSTART_KEY) as key:
            value, _ = winreg.QueryValueEx(key, _AUTOSTART_NAME)
        state['enabled'] = 'LenBot.exe' in str(value)
    except OSError:
        state['enabled'] = False
    return state

def _autostart_write(enabled: bool) -> dict:
    import sys as _sys
    if _sys.platform != 'win32':
        raise HTTPException(400, '开机自启动只支持 Windows')
    import winreg
    if enabled:
        exe = _autostart_exe()
        if exe is None:
            raise HTTPException(409, '找不到 LenBotDesktop\\LenBot.exe，请确认桌面程序还在原位置')
        with winreg.CreateKeyEx(winreg.HKEY_CURRENT_USER, _AUTOSTART_KEY, 0,
                                winreg.KEY_SET_VALUE) as key:
            winreg.SetValueEx(key, _AUTOSTART_NAME, 0, winreg.REG_SZ,
                              '"' + str(exe) + '" --start-all')
    else:
        try:
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, _AUTOSTART_KEY, 0,
                                winreg.KEY_SET_VALUE) as key:
                winreg.DeleteValue(key, _AUTOSTART_NAME)
        except OSError:
            pass
    return _autostart_read()

