def sticker_nudge_streak(config) -> int:
    root = getattr(config, "_instance_root", None)
    if root is None:
        return 3
    try:
        raw = json.loads((Path(root) / "local-settings.json").read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return 3
    value = raw.get("sticker_nudge_streak", 3) if isinstance(raw, dict) else 3
    return max(1, min(value, 20)) if type(value) is int else 3


